# Using Vicuna with SwiftUI

You can't run Vicuna directly in a SwiftUI app due to its size and computational requirements, but you can integrate it through a backend API. Here's how to do it:

## Option 1: API-Based Integration (Recommended)

### 1. Set Up a Backend Server

First, host Vicuna on a server (using vLLM, FastAPI, etc.):

```python
# backend/server.py
from fastapi import FastAPI
from pydantic import BaseModel
import requests

app = FastAPI()

class Message(BaseModel):
    message: str

@app.post("/chat")
async def chat(msg: Message):
    response = requests.post(
        "http://localhost:8000/v1/chat/completions",
        json={"model": "vicuna", "messages": [{"role": "user", "content": msg.message}]}
    )
    return response.json()
```

### 2. SwiftUI Implementation

```swift
// Models/Message.swift
struct Message: Identifiable, Codable {
    let id = UUID()
    var role: String
    var content: String
}

// Services/APIService.swift
class APIService: ObservableObject {
    @Published var messages: [Message] = []
    @Published var isLoading = false

    private let baseURL = "https://your-backend.com"

    func sendMessage(_ text: String) async {
        isLoading = true
        defer { isLoading = false }

        messages.append(Message(role: "user", content: text))

        guard let url = URL(string: "\(baseURL)/chat") else { return }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body = ["message": text]
        request.httpBody = try? JSONSerialization.data(withJSONObject: body)

        do {
            let (data, _) = try await URLSession.shared.data(for: request)
            let response = try JSONDecoder().decode([String: String].self, from: data)

            await MainActor.run {
                if let assistantMessage = response["response"] {
                    messages.append(Message(role: "assistant", content: assistantMessage))
                }
            }
        } catch {
            print("Error: \(error)")
        }
    }
}

// Views/ChatView.swift
struct ChatView: View {
    @StateObject private var apiService = APIService()
    @State private var inputText = ""

    var body: some View {
        VStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 12) {
                    ForEach(apiService.messages) { message in
                        HStack {
                            if message.role == "user" {
                                Spacer()
                                Text(message.content)
                                    .padding()
                                    .background(Color.blue)
                                    .foregroundColor(.white)
                                    .cornerRadius(12)
                            } else {
                                Text(message.content)
                                    .padding()
                                    .background(Color.gray.opacity(0.2))
                                    .cornerRadius(12)
                                Spacer()
                            }
                        }
                    }

                    if apiService.isLoading {
                        ProgressView()
                            .frame(maxWidth: .infinity)
                    }
                }
                .padding()
            }

            HStack {
                TextField("Type a message...", text: $inputText)
                    .textFieldStyle(RoundedBorderTextFieldStyle())
                    .disabled(apiService.isLoading)

                Button("Send") {
                    Task {
                        await apiService.sendMessage(inputText)
                        inputText = ""
                    }
                }
                .disabled(inputText.isEmpty || apiService.isLoading)
            }
            .padding()
        }
        .navigationTitle("Vicuna Chat")
    }
}
```

## Option 2: Use Cloud AI Services

Instead of self-hosting Vicuna, use existing APIs:

```swift
// Using OpenAI-compatible API (many Vicuna hosts support this)
class VicunaService: ObservableObject {
    private let apiKey = "your-api-key"
    private let endpoint = "https://api.vicuna-host.com/v1/chat/completions"

    func chat(prompt: String) async throws -> String {
        var request = URLRequest(url: URL(string: endpoint)!)
        request.httpMethod = "POST"
        request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body: [String: Any] = [
            "model": "vicuna-13b",
            "messages": [["role": "user", "content": prompt]],
            "temperature": 0.7
        ]

        request.httpBody = try JSONSerialization.data(withJSONObject: body)

        let (data, _) = try await URLSession.shared.data(for: request)
        let json = try JSONSerialization.jsonObject(with: data) as? [String: Any]
        let choices = json?["choices"] as? [[String: Any]]
        let message = choices?.first?["message"] as? [String: Any]

        return message?["content"] as? String ?? "No response"
    }
}
```

## Option 3: On-Device Alternative (Core ML)

For true on-device AI, consider smaller models:

```swift
// Using Apple's Core ML with a quantized model
import CoreML

class LocalAIManager {
    private let model: YourSmallMLModel?

    init() {
        // Load a small quantized model (< 1GB)
        self.model = try? YourSmallMLModel(configuration: MLModelConfiguration())
    }

    func generateResponse(prompt: String) -> String {
        // Implement inference logic
        return "Response from local model"
    }
}
```

## Important Considerations

| Aspect | Recommendation |
|--------|---------------|
| **Model Size** | Vicuna 7B+ requires 14GB+ RAM |
| **iOS Devices** | Cannot run Vicuna locally |
| **Latency** | API calls add network delay |
| **Cost** | Hosting/server costs apply |
| **Privacy** | Data sent to external servers |

## Popular Vicuna Hosting Options

1. **Replicate** - Easy API access
2. **Hugging Face Inference** - Free tier available
3. **Self-hosted** - Full control, higher cost
4. **Together AI** - Optimized for LLMs

## Security Best Practices

```swift
// Store API keys securely
import Security

class KeychainManager {
    static func save(key: String, value: String) {
        let data = value.data(using: .utf8)!
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrAccount as String: key,
            kSecValueData as String: data
        ]
        SecItemAdd(query as CFDictionary, nil)
    }
}
```

**Recommendation**: Start with a cloud API service for prototyping, then consider self-hosting for production if you need more control or cost optimization.

